WITH source_data AS (SELECT DISTINCT LISTING_ID, MAKER, MODEL, VOLUME, CONDITION, ITEM_NAME FROM {{ ref('int_enriched_transactions') }}), enriched_data AS (SELECT MD5(CONCAT(LISTING_ID, MAKER, MODEL, VOLUME, CONDITION, ITEM_NAME)) AS ITEM_ID, LISTING_ID, MAKER, MODEL, VOLUME, CONDITION, ITEM_NAME FROM source_data) SELECT * FROM enriched_data